1	import { PersistedRecord } from "./persisted_record";
2	
3	export interface ReaderSettings {
4	  readonly fontFamily: "serif" | "sans" | "mono";
5	  readonly fontSize: number;
6	  readonly lineHeight: number;
7	  readonly maxWidth: number;
8	  readonly autoScroll: boolean;
9	  readonly autoNextChapter: boolean;
10	}
11	
12	const DEFAULTS: ReaderSettings = Object.freeze({
13	  fontFamily: "serif",
14	  fontSize: 18,
15	  lineHeight: 1.8,
16	  maxWidth: 700,
17	  autoScroll: true,
18	  autoNextChapter: false,
19	});
20	
21	const FONT_FAMILIES = ["serif", "sans", "mono"] as const;
22	
23	function coerce(raw: unknown): Partial<ReaderSettings> {
24	  if (!raw || typeof raw !== "object") return {};
25	  const r = raw as Record<string, unknown>;
26	  const out: { -readonly [K in keyof ReaderSettings]?: ReaderSettings[K] } = {};
27	  if (
28	    typeof r.fontFamily === "string" &&
29	    (FONT_FAMILIES as ReadonlyArray<string>).includes(r.fontFamily)
30	  ) {
31	    out.fontFamily = r.fontFamily as ReaderSettings["fontFamily"];
32	  }
33	  if (typeof r.fontSize === "number") out.fontSize = r.fontSize;
34	  if (typeof r.lineHeight === "number") out.lineHeight = r.lineHeight;
35	  if (typeof r.maxWidth === "number") out.maxWidth = r.maxWidth;
36	  if (typeof r.autoScroll === "boolean") out.autoScroll = r.autoScroll;
37	  if (typeof r.autoNextChapter === "boolean")
38	    out.autoNextChapter = r.autoNextChapter;
39	  return out;
40	}
41	
42	const store = new PersistedRecord<ReaderSettings>(
43	  "readaloud-reader-settings",
44	  DEFAULTS,
45	  coerce,
46	);
47	
48	type SettingsListener = (s: Readonly<ReaderSettings>) => void;
49	const listeners = new Set<SettingsListener>();
50	
51	export const readerSettings = {
52	  get(): Readonly<ReaderSettings> {
53	    return store.get();
54	  },
55	  set(patch: Partial<ReaderSettings>): Readonly<ReaderSettings> {
56	    const next = store.set(patch);
57	    for (const fn of listeners) fn(next);
58	    return next;
59	  },
60	  subscribe(fn: SettingsListener): () => void {
61	    listeners.add(fn);
62	    return () => listeners.delete(fn);
63	  },
64	  defaults: DEFAULTS,
65	};
