    window.addEventListener("keydown", (ev) => {
      keyDown = ev.key;
    });
    window.addEventListener("keyup", () => {
      keyDown = null;
    });
    window.addEventListener(
      "click",
      (ev) => {
        if (keyDown === "c") {
          ev.preventDefault();
          ev.stopImmediatePropagation();
          reloader.openEditorAtCaller(ev.target);
        } else if (keyDown === "d") {
          ev.preventDefault();
          ev.stopImmediatePropagation();
          reloader.openEditorAtDef(ev.target);
        }
